export const CLASS_CTF_LABS = {
  xss: { title: 'Escaped profile card', objective: 'Make a profile value containing markup display as literal text in both the profile and moderator preview.', setup: 'Use a local template with autoescaping enabled and a harmless marker such as <b>hello</b>. Do not execute script or test a real user session.', steps: ['Find every render path for the saved display name.', 'Check whether the preview uses a different template or raw-HTML API.', 'Patch the output context and add an assertion that the marker creates no HTML element.'], success: 'Both views show the marker as text; the DOM contains no injected element.', code: 'profile = render_template(\"profile.html\", name=fixture_name)\\n# template keeps {{ name }} escaped' },
  injection: { title: 'Search filter stays data', objective: 'Make a search filter treat user input as one value and prevent it changing the query structure.', setup: 'Use a disposable local database with two synthetic rows and a mocked database driver.', steps: ['Locate the query construction point.', 'Switch to the driver’s bind parameters.', 'Test a normal value and a quote-containing inert value; inspect the query shape, not private data.'], success: 'Both inputs are treated as values and the query structure stays fixed.', code: 'rows = db.execute(\"SELECT id FROM users WHERE email = ?\", (email,))' },
  info: { title: 'Private fields stay private', objective: 'Return a profile response that contains only fields authorized for the current viewer.', setup: 'Seed one public profile and one private test account; use fake values only.', steps: ['Compare the API serializer with the product’s public-field policy.', 'Create an explicit response shape.', 'Assert private columns are absent for both owner and non-owner responses.'], success: 'Response shape matches the access policy; no secret is sent and then hidden by the UI.', code: 'payload = {\"id\": user.id, \"display_name\": user.display_name}' },
  access: { title: 'Two-user document boundary', objective: 'Ensure the second synthetic user cannot read or change the first user’s document.', setup: 'Create two local test users and two records in a disposable database.', steps: ['Write the owner/action policy in one sentence.', 'Scope lookup and mutation to the authenticated principal.', 'Test owner, other user, and anonymous cases; check state after denied writes.'], success: 'Owner access succeeds; other-user and anonymous requests fail without changing the record.', code: 'doc = Document.objects.get(id=doc_id, owner_id=request.user.id)' },
  auth: { title: 'Single-use recovery flow', objective: 'Make a recovery token account-bound, short-lived, and unusable after the first successful reset.', setup: 'Use a local mail sink and disposable accounts; do not send real email or use real credentials.', steps: ['Review token generation, storage, expiry, and consumption.', 'Store a verifier rather than the raw token.', 'Test wrong-account, expired, replayed, and valid tokens.'], success: 'Only the first valid token for its intended test account succeeds.', code: 'token = secrets.token_urlsafe(32)\\nstore_hash(user.id, sha256(token), expires_at)' },
  csrf: { title: 'State change needs intent', objective: 'Reject a cookie-authenticated state change when its request-intent token is missing or invalid.', setup: 'Run the app locally with a test session and a harmless preference setting.', steps: ['Identify every route that changes state.', 'Add framework CSRF validation to those routes.', 'Test valid in-app submission and missing/invalid token cases.'], success: 'A valid token changes only the test preference; invalid or missing tokens leave it unchanged.', code: '@csrf_protect\\ndef update_preference(request):\\n    ...  # parse and validate only after middleware accepts the token' },
  ssrf: { title: 'Partner preview allowlist', objective: 'Allow a preview only for configured partner IDs and never fetch a caller-supplied destination.', setup: 'Use a local mock partner server and an outbound-request recorder; do not probe internal/cloud addresses.', steps: ['Replace raw URL input with a fixed partner ID.', 'Resolve IDs through reviewed configuration.', 'Test unknown IDs and redirects with the recorder; confirm no unapproved destination is contacted.'], success: 'Only the configured mock host receives a request; unknown IDs are rejected.', code: 'target = APPROVED_PARTNERS.get(partner_id)\\nif target is None: raise ValueError(\"unknown partner\")' },
  path: { title: 'Files remain in the storage root', objective: 'Make file retrieval use an authorized opaque ID and ensure the resolved file stays under a temporary storage directory.', setup: 'Use a temporary directory with synthetic files only; never read host files.', steps: ['Remove direct use of a request path fragment.', 'Look up an opaque file ID after checking owner.', 'Test a normal file, unknown ID, and traversal-like name against the temporary root.'], success: 'Only the authorized synthetic file is returned; all other cases are denied.', code: 'resolved = (root / server_name).resolve()\\nif root not in resolved.parents: raise ValueError(\"outside root\")' },
  race: { title: 'One coupon, one successful claim', objective: 'Enforce one redemption for a synthetic coupon when duplicate requests arrive together.', setup: 'Use one disposable database row, a small bounded local concurrency test, and no payment or external side effects.', steps: ['State the invariant: at most one redemption succeeds.', 'Implement an atomic conditional update or transaction.', 'Submit a small fixed number of concurrent requests and inspect committed state.'], success: 'Exactly one request changes the row; all others receive a conflict and no duplicate side effect occurs.', code: 'UPDATE coupon SET used = TRUE WHERE id = ? AND used = FALSE;\\n-- accept only when affected-row count is exactly 1' },
  logic: { title: 'Server recalculates checkout', objective: 'Ensure a client cannot set the final price or eligibility flag for a synthetic order.', setup: 'Use a local cart with fake catalog prices and a test discount rule.', steps: ['Send item IDs, not trusted totals or roles.', 'Reload prices and eligibility server-side.', 'Test normal, expired-offer, and altered-total submissions.'], success: 'The server computes the same authorized total for each request and rejects invalid transitions.', code: 'total = sum(catalog[item_id].current_price for item_id in authorized_ids)' },
  http: { title: 'Consistent browser boundary', objective: 'Check security headers and same-origin navigation in the local app configuration.', setup: 'Use a local development server and inspect its response headers; do not send malformed traffic to shared services.', steps: ['Set an explicit framing and content-type policy.', 'Parse return URLs and compare exact origins.', 'Verify headers and reject an external redirect destination.'], success: 'The response has the expected policy headers; only an approved same-origin destination is used.', code: 'target = new URL(next, APP_ORIGIN)\\nif (target.origin !== APP_ORIGIN) throw new Error(\"external origin\")' },
  crypto: { title: 'Token generation and storage', objective: 'Generate an unpredictable test recovery token and persist only its verifier with a short expiry.', setup: 'Use a local token store with synthetic accounts; do not use a production key or real credential.', steps: ['Use the platform cryptographic random generator.', 'Store a one-way verifier, account binding, expiry, and used state.', 'Test valid, expired, replayed, and wrong-account cases.'], success: 'Only the intended, unexpired, unused test token is accepted.', code: 'token = secrets.token_urlsafe(32)\\nstore(user_id, sha256(token), expires_at, used=False)' },
  misconf: { title: 'Production config guard', objective: 'Make the service refuse to start with debug mode enabled or a missing secret.', setup: 'Use a local configuration fixture; never print or commit actual environment secrets.', steps: ['List required settings and their safe production values.', 'Fail startup if a required secret is missing or a debug flag is on.', 'Check logs and client bundles for secret exposure.'], success: 'Unsafe settings fail closed and no secret appears in client assets or logs.', code: 'if DEBUG or not APP_SECRET:\\n    raise RuntimeError(\"unsafe production configuration\")' },
  dos: { title: 'Bounded parser', objective: 'Reject an oversized input before expensive parsing or allocation.', setup: 'Use a local fixture and small controlled input sizes; do not run load tests.', steps: ['Set a documented request/body limit.', 'Check size before parsing or allocating.', 'Test just below, at, and above the boundary while measuring one request at a time.'], success: 'In-range input works; oversized input is rejected promptly without large allocation.', code: 'if len(body) > MAX_BODY_BYTES:\\n    raise RequestTooLarge()' },
  redirect: { title: 'Safe return destination', objective: 'Accept a local relative destination and fall back for external URLs.', setup: 'Use a local app origin and a controlled test URL string; no external navigation is needed.', steps: ['Parse the return value with the platform URL parser.', 'Compare exact origin and expected path rules.', 'Test relative, same-origin, and external values.'], success: 'Only approved same-origin paths are followed; other values use a safe local fallback.', code: 'target = new URL(next, APP_ORIGIN)\\nreturn target.origin === APP_ORIGIN ? target.pathname : \"/home\"' },
  memory: { title: 'Buffer boundary CTF', objective: 'Find and patch the unsafe copy into a fixed-size stack buffer using compiler diagnostics.', setup: 'Run only a local toy program built with AddressSanitizer. The challenge demonstrates a crash; it has no shell, network, or control-flow payload.', steps: ['Save the vulnerable listing as lab-vulnerable.c and compile with -fsanitize=address.', 'Run once with a short name, then with 8 ordinary characters for an 8-byte buffer; read the sanitizer’s bounds report.', 'Save the fixed listing as lab-fixed.c; it rejects values that leave no room for the terminating NUL.', 'Re-run lengths 0, 7, 8, and a longer value; the patched program must reject anything that does not fit.'], success: 'You can point to the exact write past the buffer, explain why the NUL byte matters, and show the patched version rejects oversized input.', code: '# lab-vulnerable.c — intentionally unsafe local CTF fixture\n#include <stdio.h>\n#include <string.h>\nstatic int greet(const char *input) {\n    char name[8];\n    strcpy(name, input); /* BUG: no capacity check */\n    puts(name);\n    return 0;\n}\nint main(int argc, char **argv) {\n    if (argc != 2) { fprintf(stderr, \"usage: lab <name>\\\\n\"); return 2; }\n    return greet(argv[1]);\n}\n\n# lab-fixed.c — safe version\n#include <stdio.h>\n#include <string.h>\nstatic int greet(const char *input) {\n    char name[8];\n    size_t length = strlen(input);\n    if (length >= sizeof name) return 1; /* reserve space for NUL */\n    memcpy(name, input, length + 1);\n    puts(name);\n    return 0;\n}\nint main(int argc, char **argv) {\n    if (argc != 2) return 2;\n    return greet(argv[1]);\n}\n\n# Build and run only in the local lab\ncc -Wall -Wextra -fsanitize=address -fno-omit-frame-pointer lab-vulnerable.c -o lab-vulnerable\n./lab-vulnerable visitor\n./lab-vulnerable 12345678\ncc -Wall -Wextra -fsanitize=address -fno-omit-frame-pointer lab-fixed.c -o lab-fixed\n./lab-fixed 12345678' },
  ui: { title: 'Trusted message origin', objective: 'Make a browser message update local UI state only when it comes from the expected origin and has the expected shape.', setup: 'Use two local pages on distinct test origins or a unit-test event fixture; do not send messages to real accounts.', steps: ['Validate exact event.origin and expected window source.', 'Validate the message schema before updating state.', 'Test accepted and rejected origins and malformed data.'], success: 'Only the trusted fixture updates the view; invalid messages are ignored.', code: 'if (event.origin !== TRUSTED_ORIGIN) return;\\nif (!isExpectedMessage(event.data)) return;\\nsetViewState(event.data.status)' },
  other: { title: 'Turn a broad label into a testable rule', objective: 'Translate a vague report label into one concrete security invariant and a regression check.', setup: 'Use a synthetic report and local fixture; do not assume the label proves a particular exploit path.', steps: ['Name the protected asset and actor.', 'Trace the decision point and observed behavior.', 'Write one allowed and one denied test for the property actually demonstrated.'], success: 'The lesson distinguishes evidence from assumptions and the regression protects a specific invariant.', code: 'assert allowed_case() is True\\nassert denied_case() is False\\nassert protected_state_after_denial == protected_state_before' },
};

